package com.johnny.hotel.damage;import com.johnny.hotel.entity.FolioItem;import lombok.RequiredArgsConstructor;import org.springframework.stereotype.Component;import java.util.*;import static com.johnny.hotel.service.support.BillingRules.require;
@Component@RequiredArgsConstructor public class DamageLedgerRules{private final DamageAssessmentMapper db;public List<FolioItem> validate(Long folio,List<FolioItem> ledger){var used=new HashSet<Long>();for(var a:db.forFolio(folio)){if(a.getStatus()==DamageAssessmentStatus.PENDING.getCode())throw new com.johnny.hotel.exception.BusinessException("Pending damage assessments must be resolved before checkout");if(a.getStatus()==DamageAssessmentStatus.UNPOSTED_CLOSED_FOLIO.getCode())throw new com.johnny.hotel.exception.BusinessException("Unposted closed-folio damage cannot exist on an open checkout");if(a.getResponsibility()==DamageResponsibility.CUSTOMER.getCode()){var item=ledger.stream().filter(x->Objects.equals(x.getId(),a.getFolioItemId())).findFirst().orElse(null);require(item!=null&&used.add(item.getId())&&"DAMAGE_ASSESSMENT".equals(item.getSourceType())&&Objects.equals(item.getSourceId(),a.getId())&&"DAMAGE_CHARGE".equals(item.getItemType())&&item.getAmount().compareTo(a.getAssessedCharge())==0,"Damage charge does not match its assessment");}else require(a.getFolioItemId()==null&&a.getAssessedCharge()==null,"Hotel or waived damage cannot charge the guest");}for(var item:ledger)if("DAMAGE_ASSESSMENT".equals(item.getSourceType()))require(used.contains(item.getId()),"Orphan or duplicate damage charge");return ledger.stream().filter(x->!used.contains(x.getId())).toList();}}
